  /** 登记一次页修改。注意：此时不要写数据页 */
  write(pageId: number, data: Uint8Array): Promise<void>;
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface WalStore {
  begin(): WalTransaction;
  readPage(pageId: number): Promise<Uint8Array>;
  /** 重放日志里所有已提交的事务，返回重放的事务数 */
  recover(): Promise<number>;
}

