import type { Row } from './contract';

/** 在我的快照之后已经有人改过同一个 key */
export class WriteConflictError extends Error {
  txId: number;
  key: string;

  constructor(txId: number, key: string) {
    super('transaction ' + txId + ' conflicts on "' + key + '"');
    this.name = 'WriteConflictError';
    this.txId = txId;
