}

export type CompareOp = '=' | '!=' | '<' | '<=' | '>' | '>=';
export type BinaryOp = CompareOp | 'AND' | 'OR';

export type Expr =
  | { kind: 'column'; name: string }
  | { kind: 'literal'; value: number | string }
  | { kind: 'binary'; op: BinaryOp; left: Expr; right: Expr };

