// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface PagerOptions {
//   capacity: number;
// }
//
// interface Frame {
//   data: Uint8Array;
//   dirty: boolean;
// }

export function createPager(disk, options) {
    const capacity = Math.max(1, options.capacity);
    // Map 按插入顺序迭代，命中时 delete + set 把这一页挪到最新端，
    // 于是第一个 key 永远是最久未使用的那一页。
    const frames = new Map();
    const stats = { hits: 0, misses: 0, evictions: 0, dirty: 0 };
    function touch(pageId, frame) {
        frames.delete(pageId);
        frames.set(pageId, frame);
    }
    function countDirty() {
        let dirty = 0;
        for (const frame of Array.from(frames.values())) {
            if (frame.dirty)
                dirty += 1;
        }
        return dirty;
    }
    async function evictIfNeeded() {
        while (frames.size > capacity) {
            const oldest = frames.keys().next();
            if (oldest.done)
                return;
            const pageId = oldest.value;
            const frame = frames.get(pageId);
            frames.delete(pageId);
            // 脏页必须先写回，否则用户写过的数据会随着淘汰一起消失
            if (frame.dirty)
                await disk.writePage(pageId, frame.data);
            stats.evictions += 1;
        }
    }
    async function load(pageId) {
        const cached = frames.get(pageId);
        if (cached) {
            stats.hits += 1;
            touch(pageId, cached);
            return cached;
        }
        stats.misses += 1;
        const data = await disk.readPage(pageId);
        const frame = { data, dirty: false };
        frames.set(pageId, frame);
        await evictIfNeeded();
        return frame;
    }
    return {
        async readPage(pageId) {
            const frame = await load(pageId);
            // 交出副本：调用方改坏了返回值也不会污染缓存
            return frame.data.slice();
        },
        async writePage(pageId, data) {
            const existing = frames.get(pageId);
            if (existing) {
                existing.data = data.slice();
                existing.dirty = true;
                touch(pageId, existing);
            }
            else {
                frames.set(pageId, { data: data.slice(), dirty: true });
                await evictIfNeeded();
            }
            stats.dirty = countDirty();
        },
        async allocatePage() {
            const pageId = await disk.allocatePage();
            frames.set(pageId, { data: new Uint8Array(0), dirty: false });
            frames.delete(pageId);
            return pageId;
        },
        async flush() {
            for (const entry of Array.from(frames.entries())) {
                const frame = entry[1];
                if (!frame.dirty)
                    continue;
                await disk.writePage(entry[0], frame.data);
                frame.dirty = false;
            }
            // 攒够了一次 fsync：它是这一层最贵的操作
            await disk.fsync();
            stats.dirty = 0;
        },
        stats() {
            return { ...stats, dirty: countDirty() };
        },
    };
}

