// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export type LockMode = 'shared' | 'exclusive';
//
// export interface LockManager {
//   acquire(txId: number, resource: string, mode: LockMode): Promise<void>;
//   release(txId: number): void;
//   holders(resource: string): number[];
//   waiterCount(): number;
// }
//
// interface Waiter {
//   txId: number;
//   mode: LockMode;
//   resolve: () => void;
// }

export class DeadlockError extends Error {
    constructor(txId) {
        super('transaction ' + txId + ' was aborted to break a deadlock');
        this.name = 'DeadlockError';
        this.txId = txId;
    }
}
export function createLockManager() {
    const held = new Map();
    const queues = new Map();
    const byTx = new Map();
    function holdersOf(resource) {
        const existing = held.get(resource);
        if (existing)
            return existing;
        const created = new Map();
        held.set(resource, created);
        return created;
    }
    function queueOf(resource) {
        const existing = queues.get(resource);
        if (existing)
            return existing;
        const created = [];
        queues.set(resource, created);
        return created;
    }
    function compatible(resource, txId, mode) {
        const current = holdersOf(resource);
        if (current.size === 0)
            return true;
        // 唯一持有者是自己：重复申请或升级，都直接放行
        if (current.size === 1 && current.has(txId))
            return true;
        if (mode === 'exclusive')
            return false;
        // 共享请求：只要没有别人拿着排他锁就相容
        for (const entry of Array.from(current.entries())) {
            if (entry[0] !== txId && entry[1] === 'exclusive')
                return false;
        }
        return true;
    }
    function grant(resource, txId, mode) {
        const current = holdersOf(resource);
        // 已经是排他锁就不要被一次共享申请降级
        const existing = current.get(txId);
        current.set(txId, existing === 'exclusive' ? 'exclusive' : mode);
        const owned = byTx.get(txId) || new Set();
        owned.add(resource);
        byTx.set(txId, owned);
    }
    function drain(resource) {
        const queue = queueOf(resource);
        // 只从队头放行：相容的请求也不许插队，否则源源不断的读会饿死写
        while (queue.length > 0 && compatible(resource, queue[0].txId, queue[0].mode)) {
            const waiter = queue.shift();
            grant(resource, waiter.txId, waiter.mode);
            waiter.resolve();
        }
        if (queue.length === 0)
            queues.delete(resource);
    }
    /**
     * 等待图：每个正在等待的事务，连边指向它所等资源的每个持有者。
     * 把新请求这条边也加进去，从请求方出发能走回自己就是环。
     */
    function wouldCycle(txId, resource) {
        const waitsFor = new Map();
        const addEdges = (waiter, target) => {
            const set = waitsFor.get(waiter) || new Set();
            for (const holder of Array.from(holdersOf(target).keys())) {
                if (holder !== waiter)
                    set.add(holder);
            }
            waitsFor.set(waiter, set);
        };
        for (const entry of Array.from(queues.entries())) {
            for (const waiter of entry[1])
                addEdges(waiter.txId, entry[0]);
        }
        addEdges(txId, resource);
        const seen = new Set();
        const stack = Array.from(waitsFor.get(txId) || []);
        while (stack.length > 0) {
            const current = stack.pop();
            if (current === txId)
                return true;
            if (seen.has(current))
                continue;
            seen.add(current);
            for (const next of Array.from(waitsFor.get(current) || []))
                stack.push(next);
        }
        return false;
    }
    return {
        async acquire(txId, resource, mode) {
            const queue = queueOf(resource);
            if (queue.length === 0 && compatible(resource, txId, mode)) {
                grant(resource, txId, mode);
                return;
            }
            // 判死锁要在进队列**之前**：进了队列再发现成环，
            // 就得把已经在等的人也叫醒，处理起来麻烦得多
            if (wouldCycle(txId, resource))
                throw new DeadlockError(txId);
            await new Promise((resolve) => {
                queue.push({ txId, mode, resolve });
            });
        },
        release(txId) {
            const owned = byTx.get(txId);
            if (!owned)
                return;
            for (const resource of Array.from(owned)) {
                holdersOf(resource).delete(txId);
            }
            byTx.delete(txId);
            // 释放之后必须主动唤醒，等待者不会自己醒过来
            for (const resource of Array.from(owned))
                drain(resource);
        },
        holders(resource) {
            return Array.from(holdersOf(resource).keys());
        },
        waiterCount() {
            let total = 0;
            for (const queue of Array.from(queues.values()))
                total += queue.length;
            return total;
        },
    };
}

