// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface MvccTransaction {
//   id: number;
//   read(key: string): Row | null;
//   write(key: string, row: Row | null): void;
//   commit(): void;
//   rollback(): void;
// }
//
// export interface MvccStore {
//   begin(): MvccTransaction;
//   current(key: string): Row | null;
//   chainLength(key: string): number;
//   vacuum(): number;
//   activeCount(): number;
// }
//
// interface Version {
//   createdBy: number;
//   /** null 表示还没提交 */
//   commitSeq: number | null;
//   row: Row | null;
// }

export class WriteConflictError extends Error {
    constructor(txId, key) {
        super('transaction ' + txId + ' conflicts on "' + key + '"');
        this.name = 'WriteConflictError';
        this.txId = txId;
        this.key = key;
    }
}
export function createMvccStore() {
    let nextTxId = 1;
    // 全局提交序号。可见性和冲突判定都只是在比较两个整数
    let commitSeq = 0;
    const chains = new Map();
    const active = new Map();
    function chainOf(key) {
        const existing = chains.get(key);
        if (existing)
            return existing;
        const created = [];
        chains.set(key, created);
        return created;
    }
    function latestCommitted(key) {
        const versions = chains.get(key) || [];
        for (let index = versions.length - 1; index >= 0; index -= 1) {
            if (versions[index].commitSeq !== null)
                return versions[index];
        }
        return null;
    }
    return {
        begin() {
            const id = nextTxId;
            nextTxId += 1;
            const startSeq = commitSeq;
            active.set(id, startSeq);
            const written = new Set();
            let settled = false;
            function discardOwn() {
                for (const key of Array.from(written)) {
                    const versions = chainOf(key);
                    chains.set(key, versions.filter((version) => !(version.createdBy === id && version.commitSeq === null)));
                }
                written.clear();
            }
            return {
                id,
                read(key) {
                    const versions = chains.get(key) || [];
                    // 从新往旧扫，第一个可见的就是答案。
                    // 反过来扫会永远返回最初那个值
                    for (let index = versions.length - 1; index >= 0; index -= 1) {
                        const version = versions[index];
                        if (version.createdBy === id)
                            return version.row;
                        // <= 而不是 <：开始那一刻已经提交的必须可见
                        if (version.commitSeq !== null && version.commitSeq <= startSeq)
                            return version.row;
                    }
                    return null;
                },
                write(key, row) {
                    if (settled)
                        throw new Error('transaction ' + id + ' has already finished');
                    const versions = chainOf(key);
                    const mine = versions.filter((version) => version.createdBy === id && version.commitSeq === null)[0];
                    if (mine) {
                        mine.row = row;
                    }
                    else {
                        versions.push({ createdBy: id, commitSeq: null, row });
                    }
                    written.add(key);
                },
                commit() {
                    if (settled)
                        throw new Error('transaction ' + id + ' has already finished');
                    // 条件是「有没有**任何**版本在我的快照之后提交」，
                    // 只比较最新版本会在连续提交时漏判
                    for (const key of Array.from(written)) {
                        for (const version of chainOf(key)) {
                            if (version.commitSeq !== null && version.commitSeq > startSeq) {
                                // 先把自己造的版本摘掉再抛：留在链里的话
                                // 既不可见也 vacuum 不掉，链只会越来越长
                                discardOwn();
                                settled = true;
                                active.delete(id);
                                throw new WriteConflictError(id, key);
                            }
                        }
                    }
                    commitSeq += 1;
                    for (const key of Array.from(written)) {
                        for (const version of chainOf(key)) {
                            if (version.createdBy === id && version.commitSeq === null) {
                                version.commitSeq = commitSeq;
                            }
                        }
                    }
                    settled = true;
                    active.delete(id);
                },
                rollback() {
                    if (settled)
                        return;
                    discardOwn();
                    settled = true;
                    active.delete(id);
                },
            };
        },
        current(key) {
            const version = latestCommitted(key);
            return version ? version.row : null;
        },
        chainLength(key) {
            return (chains.get(key) || []).length;
        },
        vacuum() {
            // 水位线取所有活跃事务里最老的那个快照：比它更旧、
            // 而且后面还有更新版本的，谁也看不见了
            let watermark = commitSeq;
            for (const startSeq of Array.from(active.values())) {
                watermark = Math.min(watermark, startSeq);
            }
            let removed = 0;
            for (const entry of Array.from(chains.entries())) {
                const versions = entry[1];
                let keepFrom = -1;
                for (let index = versions.length - 1; index >= 0; index -= 1) {
                    const version = versions[index];
                    if (version.commitSeq !== null && version.commitSeq <= watermark) {
                        keepFrom = index;
                        break;
                    }
                }
                if (keepFrom > 0) {
                    removed += keepFrom;
                    chains.set(entry[0], versions.slice(keepFrom));
                }
            }
            return removed;
        },
        activeCount() {
            return active.size;
        },
    };
}

