export class SqlSyntaxError extends Error {
    constructor(message, position) {
        super(message + ' (at ' + position + ')');
        this.name = 'SqlSyntaxError';
        this.position = position;
    }
}
const KEYWORDS = [
    'SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'ASC', 'DESC',
    'LIMIT', 'INSERT', 'INTO', 'VALUES', 'AND', 'OR',
];
// 先长后短：反过来的话 '>=' 会被切成 '>' 和 '='
const TWO_CHAR_OPERATORS = ['>=', '<=', '!=', '<>'];
const ONE_CHAR_OPERATORS = ['=', '<', '>', '*', '-'];
function isSpace(ch) {
    return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
}
function isDigit(ch) {
    return ch >= '0' && ch <= '9';
}
function isWordStart(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
}
export function tokenize(sql) {
    const tokens = [];
    let index = 0;
    while (index < sql.length) {
        const ch = sql[index];
        if (isSpace(ch)) {
            index += 1;
            continue;
        }
        if (ch === "'") {
            const start = index;
            let cursor = index + 1;
            let value = '';
            let closed = false;
            while (cursor < sql.length) {
                if (sql[cursor] === "'") {
                    // 两个连写的单引号是一个转义，不是结束
                    if (sql[cursor + 1] === "'") {
                        value += "'";
                        cursor += 2;
                        continue;
                    }
                    closed = true;
                    cursor += 1;
                    break;
                }
                value += sql[cursor];
                cursor += 1;
            }
            if (!closed)
                throw new SqlSyntaxError('unterminated string literal', start);
            tokens.push({ type: 'string', value, position: start });
            index = cursor;
            continue;
        }
        if (isDigit(ch)) {
            const start = index;
            while (index < sql.length && isDigit(sql[index]))
                index += 1;
            tokens.push({ type: 'number', value: sql.slice(start, index), position: start });
            continue;
        }
        if (isWordStart(ch)) {
            const start = index;
            while (index < sql.length && (isWordStart(sql[index]) || isDigit(sql[index])))
                index += 1;
            const word = sql.slice(start, index);
            const upper = word.toUpperCase();
            const keyword = KEYWORDS.indexOf(upper) !== -1;
            // 关键字统一大写便于比较，标识符保留原样——
            // 把整条 SQL 转大写会连字符串字面量一起改掉
            const type = keyword ? 'keyword' : 'identifier';
            tokens.push({ type, value: keyword ? upper : word, position: start });
            continue;
        }
        const two = sql.slice(index, index + 2);
        if (TWO_CHAR_OPERATORS.indexOf(two) !== -1) {
            tokens.push({ type: 'operator', value: two === '<>' ? '!=' : two, position: index });
            index += 2;
            continue;
        }
        if (ONE_CHAR_OPERATORS.indexOf(ch) !== -1) {
            tokens.push({ type: 'operator', value: ch, position: index });
            index += 1;
            continue;
        }
        if (ch === '(' || ch === ')' || ch === ',') {
            tokens.push({ type: 'punctuation', value: ch, position: index });
            index += 1;
            continue;
        }
        throw new SqlSyntaxError('unexpected character "' + ch + '"', index);
    }
    tokens.push({ type: 'eof', value: '', position: sql.length });
    return tokens;
}

import { SqlSyntaxError, tokenize } from './lexer';
const COMPARE_OPS = ['=', '!=', '<', '<=', '>', '>='];
export function parse(sql) {
    const tokens = tokenize(sql);
    let index = 0;
    function peek() {
        return tokens[index];
    }
    function at(type, value) {
        const token = peek();
        return token.type === type && (value === undefined || token.value === value);
    }
    function eat(type, value) {
        const token = peek();
        if (!at(type, value)) {
            throw new SqlSyntaxError('expected ' + (value || type) + ' but found "' + (token.value || 'end of input') + '"', token.position);
        }
        index += 1;
        return token;
    }
    /* --- 表达式：一层文法一个函数，越往下优先级越高 --- */
    function parsePrimary() {
        if (at('punctuation', '(')) {
            eat('punctuation', '(');
            const inner = parseExpr();
            eat('punctuation', ')');
            return inner;
        }
        if (at('operator', '-')) {
            eat('operator', '-');
            const literal = eat('number');
            return { kind: 'literal', value: -Number(literal.value) };
        }
        if (at('number'))
            return { kind: 'literal', value: Number(eat('number').value) };
        if (at('string'))
            return { kind: 'literal', value: eat('string').value };
        if (at('identifier'))
            return { kind: 'column', name: eat('identifier').value };
        const token = peek();
        throw new SqlSyntaxError('expected a column or a literal but found "' + (token.value || 'end of input') + '"', token.position);
    }
    function parseCompare() {
        const left = parsePrimary();
        if (peek().type === 'operator' && COMPARE_OPS.indexOf(peek().value) !== -1) {
            const op = eat('operator').value;
            return { kind: 'binary', op, left, right: parsePrimary() };
        }
        return left;
    }
    function parseAnd() {
        let left = parseCompare();
        // 循环而不是递归：文法写成 X (op X)* 才不会左递归
        while (at('keyword', 'AND')) {
            eat('keyword', 'AND');
            left = { kind: 'binary', op: 'AND', left, right: parseCompare() };
        }
        return left;
    }
    function parseExpr() {
        // OR 在最外层，所以它的优先级最低
        let left = parseAnd();
        while (at('keyword', 'OR')) {
            eat('keyword', 'OR');
            left = { kind: 'binary', op: 'OR', left, right: parseAnd() };
        }
        return left;
    }
    /* --- 语句 --- */
    function parseSelect() {
        eat('keyword', 'SELECT');
        const columns = [];
        if (at('operator', '*')) {
            eat('operator', '*');
            columns.push('*');
        }
        else {
            columns.push(eat('identifier').value);
            while (at('punctuation', ',')) {
                eat('punctuation', ',');
                columns.push(eat('identifier').value);
            }
        }
        eat('keyword', 'FROM');
        const statement = { kind: 'select', columns, table: eat('identifier').value };
        if (at('keyword', 'WHERE')) {
            eat('keyword', 'WHERE');
            statement.where = parseExpr();
        }
        if (at('keyword', 'ORDER')) {
            eat('keyword', 'ORDER');
            eat('keyword', 'BY');
            const column = eat('identifier').value;
            let direction = 'asc';
            if (at('keyword', 'ASC'))
                eat('keyword', 'ASC');
            else if (at('keyword', 'DESC')) {
                eat('keyword', 'DESC');
                direction = 'desc';
            }
            statement.orderBy = { column, direction };
        }
        if (at('keyword', 'LIMIT')) {
            eat('keyword', 'LIMIT');
            statement.limit = Number(eat('number').value);
        }
        return statement;
    }
    function parseInsert() {
        eat('keyword', 'INSERT');
        eat('keyword', 'INTO');
        const table = eat('identifier').value;
        eat('keyword', 'VALUES');
        eat('punctuation', '(');
        const values = [];
        const readValue = () => {
            if (at('operator', '-')) {
                eat('operator', '-');
                values.push(-Number(eat('number').value));
            }
            else if (at('number')) {
                values.push(Number(eat('number').value));
            }
            else {
                values.push(eat('string').value);
            }
        };
        readValue();
        while (at('punctuation', ',')) {
            eat('punctuation', ',');
            readValue();
        }
        eat('punctuation', ')');
        return { kind: 'insert', table, values };
    }
    const statement = at('keyword', 'INSERT') ? parseInsert() : parseSelect();
    // 不检查这一步，"SELECT * FROM users GARBAGE" 会安静地成功，
    // 用户以为写的东西生效了，其实尾巴被丢掉了
    if (!at('eof')) {
        throw new SqlSyntaxError('unexpected "' + peek().value + '" after the statement', peek().position);
    }
    return statement;
}

