// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface Operator {
//   next(): Promise<Tuple | null>;
// }
//
// export interface ExecutionContext {
//   catalog: Catalog;
//   pager: Pager;
// }

import { createHeapFile } from './heap';
export function evaluate(expr, tuple) {
    if (expr.kind === 'column')
        return tuple[expr.name];
    if (expr.kind === 'literal')
        return expr.value;
    // 短路：一旦表达式里出现函数调用或除法，这就不再只是性能问题
    if (expr.op === 'AND') {
        return Boolean(evaluate(expr.left, tuple)) && Boolean(evaluate(expr.right, tuple));
    }
    if (expr.op === 'OR') {
        return Boolean(evaluate(expr.left, tuple)) || Boolean(evaluate(expr.right, tuple));
    }
    const left = evaluate(expr.left, tuple);
    const right = evaluate(expr.right, tuple);
    switch (expr.op) {
        case '=': return left === right;
        case '!=': return left !== right;
        case '<': return left < right;
        case '<=': return left <= right;
        case '>': return left > right;
        default: return left >= right;
    }
}
function scanOperator(table, ctx) {
    let cursor = null;
    return {
        async next() {
            if (!cursor) {
                const schema = ctx.catalog.getTable(table);
                if (!schema)
                    throw new Error('unknown table: ' + table);
                const heap = await createHeapFile(ctx.pager, schema.pages);
                cursor = heap.scan();
            }
            const entry = await cursor.next();
            // 行在算子之间是只读的：交出一个副本，上层原地改也伤不到下层
            return entry ? { ...entry.row } : null;
        },
    };
}
function filterOperator(input, predicate) {
    return {
        async next() {
            // 一次拉一行，不满足就继续拉。先把输入读干净会让整棵树变成阻塞的
            for (;;) {
                const tuple = await input.next();
                if (!tuple)
                    return null;
                if (evaluate(predicate, tuple))
                    return tuple;
            }
        },
    };
}
function projectOperator(input, columns) {
    return {
        async next() {
            const tuple = await input.next();
            if (!tuple)
                return null;
            // 造新对象，不要在原对象上删键：sort 可能还握着同一个引用
            const projected = {};
            for (const column of columns)
                projected[column] = tuple[column];
            return projected;
        },
    };
}
function sortOperator(input, column, direction) {
    let buffered = null;
    let index = 0;
    return {
        async next() {
            // 阻塞算子：不看完全部输入就不知道第一行是谁
            if (!buffered) {
                buffered = [];
                for (;;) {
                    const tuple = await input.next();
                    if (!tuple)
                        break;
                    buffered.push(tuple);
                }
                const sign = direction === 'asc' ? 1 : -1;
                buffered.sort((left, right) => {
                    if (left[column] < right[column])
                        return -sign;
                    if (left[column] > right[column])
                        return sign;
                    return 0;
                });
            }
            if (index >= buffered.length)
                return null;
            const tuple = buffered[index];
            index += 1;
            return tuple;
        },
    };
}
function limitOperator(input, count) {
    let emitted = 0;
    return {
        async next() {
            // 拉够了就再也不碰 input：这一句才是「提前退出」本身
            if (emitted >= count)
                return null;
            const tuple = await input.next();
            if (!tuple)
                return null;
            emitted += 1;
            return tuple;
        },
    };
}
function insertOperator(table, values, ctx) {
    let done = false;
    return {
        async next() {
            if (done)
                return null;
            done = true;
            const schema = ctx.catalog.getTable(table);
            if (!schema)
                throw new Error('unknown table: ' + table);
            const row = {};
            schema.columns.forEach((column, index) => {
                row[column.name] = values[index];
            });
            const heap = await createHeapFile(ctx.pager, schema.pages);
            await heap.insert(row);
            // 插入可能新开了页，目录要跟上，否则下一次扫描看不到新行
            ctx.catalog.setPages(table, heap.pages());
            return { inserted: 1 };
        },
    };
}
export function buildOperator(plan, ctx) {
    switch (plan.kind) {
        case 'scan':
            return scanOperator(plan.table, ctx);
        case 'filter':
            return filterOperator(buildOperator(plan.input, ctx), plan.predicate);
        case 'project':
            return projectOperator(buildOperator(plan.input, ctx), plan.columns);
        case 'sort':
            return sortOperator(buildOperator(plan.input, ctx), plan.column, plan.direction);
        case 'limit':
            return limitOperator(buildOperator(plan.input, ctx), plan.count);
        default:
            return insertOperator(plan.table, plan.values, ctx);
    }
}

