// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface JoinCondition {
//   left: string;
//   right: string;
// }

/** 造新对象：左行可能还要和右边其他行匹配，不能被就地改掉 */
function merge(left, right, prefix) {
    const merged = { ...left };
    for (const key of Object.keys(right)) {
        merged[prefix + '_' + key] = right[key];
    }
    return merged;
}
export function nestedLoopJoin(left, rightFactory, on, rightPrefix) {
    let leftTuple = null;
    let right = null;
    return {
        async next() {
            for (;;) {
                if (!leftTuple) {
                    leftTuple = await left.next();
                    if (!leftTuple)
                        return null;
                    // 每一条左行都要一个全新的右侧算子：复用的话
                    // 第一行之后右侧早已耗尽，结果里只剩第一行的匹配
                    right = rightFactory();
                }
                const rightTuple = await right.next();
                if (!rightTuple) {
                    leftTuple = null;
                    continue;
                }
                if (leftTuple[on.left] === rightTuple[on.right]) {
                    return merge(leftTuple, rightTuple, rightPrefix);
                }
            }
        },
    };
}
export function hashJoin(left, right, on, rightPrefix) {
    // Map 而不是普通对象：对象会把数字 1 和字符串 '1' 折叠成同一个键
    let buckets = null;
    let leftTuple = null;
    let matches = [];
    let matchIndex = 0;
    return {
        async next() {
            // build 阶段是阻塞的，而且只做一次
            if (!buckets) {
                buckets = new Map();
                for (;;) {
                    const rightTuple = await right.next();
                    if (!rightTuple)
                        break;
                    const key = rightTuple[on.right];
                    const bucket = buckets.get(key) || [];
                    bucket.push(rightTuple);
                    buckets.set(key, bucket);
                }
            }
            for (;;) {
                // 一条左行可能匹配多条右行，先把这一批吐完
                if (matchIndex < matches.length) {
                    const rightTuple = matches[matchIndex];
                    matchIndex += 1;
                    return merge(leftTuple, rightTuple, rightPrefix);
                }
                leftTuple = await left.next();
                if (!leftTuple)
                    return null;
                matches = buckets.get(leftTuple[on.left]) || [];
                matchIndex = 0;
            }
        },
    };
}

