// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export type CircuitState = 'closed' | 'open' | 'half-open';
//
// export interface CircuitBreakerOptions {
//   failureThreshold: number;
//   resetTimeoutMs: number;
//   halfOpenMax?: number;
// }
//
// export interface CircuitBreaker {
//   exec<T>(task: () => Promise<T>): Promise<T>;
//   state(): CircuitState;
// }

import { now } from '@lab/env';
export class CircuitOpenError extends Error {
    constructor() {
        super('circuit open');
        this.name = 'CircuitOpenError';
    }
}
export function createCircuitBreaker(options) {
    const halfOpenMax = options.halfOpenMax ?? 1;
    let current = 'closed';
    let failures = 0;
    let openedAt = 0;
    let probes = 0;
    // 读状态顺便完成 open -> half-open 的时间驱动转换
    function state() {
        if (current === 'open' && now() - openedAt >= options.resetTimeoutMs) {
            current = 'half-open';
            probes = 0;
        }
        return current;
    }
    function trip() {
        current = 'open';
        openedAt = now();
        failures = 0;
        probes = 0;
    }
    return {
        state,
        async exec(task) {
            const snapshot = state();
            if (snapshot === 'open')
                throw new CircuitOpenError();
            if (snapshot === 'half-open') {
                if (probes >= halfOpenMax)
                    throw new CircuitOpenError();
                probes += 1;
            }
            try {
                const result = await task();
                current = 'closed';
                failures = 0;
                probes = 0;
                return result;
            }
            catch (error) {
                if (snapshot === 'half-open') {
                    trip();
                }
                else {
                    failures += 1;
                    if (failures >= options.failureThreshold)
                        trip();
                }
                throw error;
            }
        },
    };
}

